    appearance Appearance {
      material Material {
        diffuseColor 0.9 0.6 0.2
      }
    }
    geometry Sphere {
      radius 0.9
    }
  }
}

Transform {
  translation -2.5 1.5 0
  children ScreenGroup {
    children Shape {
      appearance Appearance {
        material Material {
          diffuseColor 0 0 0
          emissiveColor 1 0.4 0.1
