      }
      geometry IndexedFaceSet {
        coordIndex [
          0,
          1,
          2,
          3,
          -1
        ]
        coord Coordinate {
          point [
            -60 -40 0,
            60 -40 0,
            60 40 0,
            -60 40 0
          ]
        }
      }
    }
  }
}

Transform {
  translation 2.5 1.5 -3
  children ScreenGroup {
    children Shape {
      appearance Appearance {
        material Material {
          diffuseColor 0 0 0
          emissiveColor 0.2 0.9 0.4
        }
      }
      geometry IndexedFaceSet {
        coordIndex [
          0,
          1,
          2,
          3,
          -1
        ]
        coord Coordinate {
          point [
            -30 -30 0,
            30 -30 0,
            30 30 0,
            -30 30 0
          ]
        }
      }
    }
  }
}

Transform {
  translation -2.5 -2 0
  children ScreenGroup {
    children Shape {
      appearance Appearance {
        material Material {
          diffuseColor 0 0 0
          emissiveColor 1 1 1
        }
      }
      geometry Text {
        string "Camera"
        fontStyle ScreenFontStyle {
          pointSize 20
        }
      }
    }
  }
}

DEF K KeySensor { }

DEF R Script {
  inputOnly      SFString on_key
  inputOutput    SFString log ""
  initializeOnly SFNode   v1 USE V1
  initializeOnly SFNode   o1 USE O1
  initializeOnly SFNode   g1 USE G1

  url "javascript:
function on_key (k)
{
   log = log + 'K' + k + ' ';
   if (k == 'a') o1 .set_bind = true;
   if (k == 'b') g1 .set_bind = true;
   if (k == 'c') o1 .fieldOfView = new MFFloat (-3, -3, 3, 3);
   if (k == 'd') v1 .set_bind = true;
   if (k == 'e') v1 .fieldOfView = 0.4;
   if (k == 'f') o1 .set_bind = true;
}
"
  directOutput TRUE
}

ROUTE K.keyPress TO R.on_key

